"Use esta lógica de contagem de páginas para o botão de upload da tela Impressão Rápida".
import * as DocumentPicker from 'expo-document-picker';
import * as FileSystem from 'expo-file-system';
import { PDFDocument } from 'pdf-lib';

/**
 * Função mestre para selecionar documento e contar páginas
 * Ideal para o público leigo: um clique, resultado imediato.
 */
export const handleFileSelectionAndCount = async () => {
  try {
    // 1. Abre o seletor de documentos (PDF e Word)
    const result = await DocumentPicker.getDocumentAsync({
      type: [
        'application/pdf', 
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      ],
      copyToCacheDirectory: true,
    });

    if (result.canceled || !result.assets) return null;

    const { uri, name, mimeType } = result.assets[0];

    // 2. Se for PDF, faz a contagem exata
    if (mimeType === 'application/pdf') {
      const base64 = await FileSystem.readAsStringAsync(uri, {
        encoding: FileSystem.EncodingType.Base64,
      });

      const pdfDoc = await PDFDocument.load(base64);
      const pageCount = pdfDoc.getPageCount();

      return {
        name,
        pageCount,
        type: 'PDF',
        uri
      };
    }

    // 3. Se for Word, retorna o arquivo (contagem de Word exige backend)
    return {
      name,
      pageCount: 1, // Valor padrão inicial
      type: 'Word',
      uri
    };

  } catch (error) {
    console.error("Erro ao processar arquivo:", error);
    return null;
  }
};
